import{_ as o,o as t,c as a,a3 as d}from"./chunks/framework.B_jDsKE8.js";const h=JSON.parse('{"title":"Output contract","description":"","frontmatter":{},"headers":[],"relativePath":"reference/output.md","filePath":"reference/output.md"}'),i={name:"reference/output.md"};function s(r,e,n,c,l,u){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="output-contract" tabindex="-1">Output contract <a class="header-anchor" href="#output-contract" aria-label="Permalink to &quot;Output contract&quot;">​</a></h1><p>How tardigrada talks on stdout/stderr — the machine-readable surface <code>--json</code> and scripts rely on. Verbs and flags: <a href="./cli.html">CLI</a> (generated from <code>--help</code>).</p><h2 id="streams" tabindex="-1">Streams <a class="header-anchor" href="#streams" aria-label="Permalink to &quot;Streams&quot;">​</a></h2><ul><li><strong>stdout</strong> carries the payload: the bare <code>age1…</code> recipient for <code>show</code>/<code>init</code>/<code>import</code>, the keyfile secret line for bare <code>export</code>, the resolved backend (<code>keyring</code>/<code>file</code>) for <code>backend</code>, JSON under <code>--json</code>.</li><li><strong>stderr</strong> carries context notes (<code>tardigrada: …</code>) and errors — including backend fallback notes (<code>no session keyring reachable (…) — using the identity file</code>). Under <code>--json</code> notes are silenced so stderr stays clean for piping; errors still emit <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr.</li></ul><h2 id="json-shapes" tabindex="-1"><code>--json</code> shapes <a class="header-anchor" href="#json-shapes" aria-label="Permalink to &quot;`--json` shapes&quot;">​</a></h2><p><code>init</code>, <code>show</code>, <code>import</code>, <code>export --out</code> share one envelope:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;backend&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;keyring&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;recipient&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;age1…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system keyring (entry tardigrada/age-identity)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>backend</code> is the resolved source kind — <code>&quot;keyring&quot;</code> or <code>&quot;file&quot;</code>.</li><li><code>source</code> describes it — a keyfile path or the store entry.</li><li><code>init</code> adds <code>&quot;created&quot;: true|false</code>; a keyring init that adopted an existing keyfile adds <code>&quot;migrated_from&quot;: &quot;&lt;keyfile path&gt;&quot;</code>.</li><li><code>import</code> adds <code>&quot;imported_from&quot;: &quot;&lt;keyfile path&gt;&quot;</code> and, when it replaces a <em>different</em> stored identity, <code>&quot;replaced_recipient&quot;</code>; <code>export --out</code> reports the same field when the destination held a different identity.</li><li><code>backend</code> emits <code>{&quot;backend&quot;,&quot;mode&quot;,&quot;pinned&quot;,&quot;source&quot;}</code>: <code>backend</code> = resolved kind, <code>mode</code> = the configured <code>TARDIGRADA_IDENTITY_BACKEND</code> (<code>keyring</code>/<code>auto</code>/<code>file</code>), <code>pinned</code> = an explicit <code>--identity-file</code>/<code>TARDIGRADA_IDENTITY_FILE</code> (or legacy <code>CUORA_</code>/<code>ARCA_IDENTITY_FILE</code>) pin is in effect.</li><li><code>manifest</code> is always JSON (flag or not): verbs, globals, env vars, backends, cuora interop note.</li></ul><p>Bare <code>export --json</code> is <strong>refused</strong> (<code>export --json needs --out PATH</code>) — a secret inside a JSON envelope invites accidental logging. Use <code>--out</code> or bare <code>export</code> for the pipeable form.</p><h2 id="warnings" tabindex="-1">Warnings <a class="header-anchor" href="#warnings" aria-label="Permalink to &quot;Warnings&quot;">​</a></h2><p>Routine context notes are suppressed under <code>--json</code>, but warnings are not — conditions that changed what the verb did emit <code>{&quot;warning&quot;: &quot;&lt;message&gt;&quot;}</code> on stderr (plain mode: <code>tardigrada: warning: &lt;message&gt;</code>). Watch for: backend fallbacks (<code>auto</code> → keyfile), an env pin overriding <code>backend=keyring</code>, an unrecognized <code>TARDIGRADA_IDENTITY_BACKEND</code>, and identity replacements.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Any failure exits <code>1</code>:</p><ul><li>plain mode: <code>tardigrada: error: &lt;message&gt;</code> on stderr</li><li><code>--json</code>: <code>{&quot;error&quot;: &quot;&lt;message&gt;&quot;}</code> on stderr</li></ul><p>Missing identity is actionable: <code>no identity at &lt;source&gt; — run </code>tardigrada init<code> first</code>. A <code>keyring</code> backend with no reachable session store fails closed: <code>identity backend unavailable: backend=keyring: … — set TARDIGRADA_IDENTITY_BACKEND=auto|file for headless/CI</code>. clap usage errors keep clap&#39;s own exit codes (<code>2</code> for parse failures).</p>',15)])])}const k=o(i,[["render",s]]);export{h as __pageData,k as default};
